const DCC_TIPO_LABEL = {
  activo:     'Activo',
  pasivo:     'Pasivo',
  patrimonio: 'Patrimonio',
  ingreso:    'Ingreso',
  egreso:     'Egreso',
};
const DCC_TIPO_BADGE = {
  activo:     'badge-info',
  pasivo:     'badge-danger',
  patrimonio: 'badge-warn',
  ingreso:    'badge-success',
  egreso:     'badge-warn',
};

let dccCuentas       = [];
let dccBusqueda      = '';
let dccFiltroTipo    = '';
let dccColapsadas    = new Set();
let dccEditandoId    = null;
let dccBuscadorTimer = null;

let dccParentPickerBusqueda   = '';
let dccParentPickerColapsadas = new Set();

function dccFmtMoney(n) {
  return Number(n || 0).toLocaleString('es-AR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

