    const data = getCtxMenuData();
    if (!data) return;
    cerrarCtxMenu();
    if (b.dataset.action === 'consultar') abrirConsultarMpCta(data.id);
    if (b.dataset.action === 'editar')    abrirAltaEdicionMpCta(data.id);
